func newReportSchedule() unsafe.Pointer { return unsafe.Pointer(new(report.ReportSchedule)) }

func newNReportSchedule(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]report.ReportSchedule, n)))
}

func ptrReportSchedule(p unsafe.Pointer, c int32) any {
	r := (*report.ReportSchedule)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DefinitionID))
	case 4:
		return &r.CronExpression
	case 5:
		return &r.Timezone
	case 6:
		return &r.Formats
	case 7:
		return &r.Delivery
	case 8:
		return &r.Alert
	case 9:
		return &r.AlertFiring
	case 10:
		return &r.Enabled
	case 11:
		return (*string)(unsafe.Pointer(&r.RunAsID))
	case 12:
		return (*string)(unsafe.Pointer(&r.LastRunID))
	case 13:
		return &r.NextRunAt
	case 14:
		return (*int64)(unsafe.Pointer(&r.ConsecutiveFailures))
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueReportSchedule(p unsafe.Pointer, c int32) any {
	r := (*report.ReportSchedule)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DefinitionID)
	case 4:
		return r.CronExpression
	case 5:
		return r.Timezone
	case 6:
		if r.Formats == nil {
			return []string{}
		}
		return r.Formats
	case 7:
		if r.Delivery == nil {
			return nil
		}
		return *r.Delivery
	case 8:
		if r.Alert == nil {
			return nil
		}
		return *r.Alert
	case 9:
		return r.AlertFiring
	case 10:
		return r.Enabled
	case 11:
		return string(r.RunAsID)
	case 12:
		if r.LastRunID == "" {
			return nil
		}
		return string(r.LastRunID)
	case 13:
		if r.NextRunAt == 0 {
			return nil
		}
		return r.NextRunAt
	case 14:
		return int64(r.ConsecutiveFailures)
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

func attachReportSchedule(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*report.ReportSchedule)(p)
	switch rel {
	case 0:
		r.RunAs = (*tenant.User)(child)
	case 1:
		r.ReportDefinition = (*report.ReportDefinition)(child)
	}
}

