func newReportView() unsafe.Pointer { return unsafe.Pointer(new(report.ReportView)) }

func newNReportView(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]report.ReportView, n)))
}

func ptrReportView(p unsafe.Pointer, c int32) any {
	r := (*report.ReportView)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DefinitionID))
	case 4:
		return (*string)(unsafe.Pointer(&r.OwnerID))
	case 5:
		return &r.Name
	case 6:
		return &r.Description
	case 7:
		return &r.Params
	case 8:
		return &r.Shared
	case 9:
		return &r.Pinned
	case 10:
		return (*string)(unsafe.Pointer(&r.Format))
	case 11:
		return &r.LastRunAt
	case 12:
		return &r.RunCount
	case 13:
		return &r.Version
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valueReportView(p unsafe.Pointer, c int32) any {
	r := (*report.ReportView)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DefinitionID)
	case 4:
		return string(r.OwnerID)
	case 5:
		return r.Name
	case 6:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 7:
		if r.Params == nil {
			return nil
		}
		return r.Params
	case 8:
		return r.Shared
	case 9:
		return r.Pinned
	case 10:
		if r.Format == "" {
			return nil
		}
		return string(r.Format)
	case 11:
		if r.LastRunAt == 0 {
			return nil
		}
		return r.LastRunAt
	case 12:
		return r.RunCount
	case 13:
		return r.Version
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

func attachReportView(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*report.ReportView)(p)
	switch rel {
	case 0:
		r.Owner = (*tenant.User)(child)
	case 1:
		r.ReportDefinition = (*report.ReportDefinition)(child)
	}
}

func init() {
	dashboardsTable.Relations[0].Target = tenantdb.UsersSchema()
	reportDefinitionsTable.Relations[0].Target = tenantdb.UsersSchema()
	reportDefinitionRevisionsTable.Relations[0].Target = ReportDefinitionsSchema()
	reportRunsTable.Relations[0].Target = tenantdb.UsersSchema()
	reportRunsTable.Relations[1].Target = ReportDefinitionsSchema()
	reportRunsTable.Relations[2].Target = ReportDefinitionRevisionsSchema()
	reportSchedulesTable.Relations[0].Target = tenantdb.UsersSchema()
	reportSchedulesTable.Relations[1].Target = ReportDefinitionsSchema()
	reportViewsTable.Relations[0].Target = tenantdb.UsersSchema()
	reportViewsTable.Relations[1].Target = ReportDefinitionsSchema()
}

